private record Peer(String tenantId, String routeId, String hostId, String deviceId, boolean host) {
    private boolean matches(RelayEnvelope value) {
        if (!tenantId.equals(value.getTenantId()) || !hostId.equals(value.getHostId())) return false;
        return host
                ? value.getDirection() == Direction.DIRECTION_HOST_TO_CLIENT
                : routeId.equals(value.getRouteId()) && deviceId.equals(value.getDeviceId())
                        && value.getDirection() == Direction.DIRECTION_CLIENT_TO_HOST;
    }
}
